{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "영리 목적 동물 전시에서 공연·묘기 교육을 하지 않는 경우에도 관람객 접촉으로 인한 동물 스트레스를 동물보호 원칙상 관리해야 하는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "영리 목적으로 동물을 전시하는 경우에는 공연·묘기 교육 여부와 관계없이 관람객의 접촉 등으로 인한 스트레스를 받지 않도록 해야 한다. 서울특별시 동물보호 조례 제31조제1항제4호는 영리목적 동물 전시 시 동물이 사람들의 접촉 등으로 인한 스트레스를 받지 않도록 할 것을 원칙으로 정하고 있다. 따라서 공연·묘기 교육을 하지 않더라도 관람객 접촉으로 인한 동물 스트레스는 동물보호 원칙상 관리해야 한다.",
          "b_ids": "동물보호:제31조제1항제4호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
